import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import { call, t } from '../api';
/** Show one letter to the moderators, on purpose: the only way its words leave the two members. */
export default class ReportModal extends FormModal {
  reason = '';
  block = true;
  className() {
    return 'SlowMailReport Modal--small';
  }
  title() {
    return t('report.title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, t('report.explain', {
      name: this.attrs.sender.displayName
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "SlowMailReport-reason"
    }, t('report.reason')), m("textarea", {
      id: "SlowMailReport-reason",
      className: "FormControl",
      rows: 3,
      maxlength: 500,
      value: this.reason,
      oninput: e => this.reason = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      checked: this.block,
      onchange: e => this.block = e.target.checked
    }), t('report.block', {
      name: this.attrs.sender.displayName
    }))), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      loading: this.loading
    }, t('report.send'))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    call('POST', '/letters/' + this.attrs.letterId + '/report', {
      reason: this.reason,
      block: this.block
    }).then(() => {
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('report.done'));
      this.attrs.ondone(this.block);
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-slow-mail', 'forum/components/ReportModal', ReportModal);